    point3: "Moottori, joka päättää onko kyseessä haavoittuvuus, on aina puhdasta hahmontunnistusta, ei koskaan tekoälymalli: ei hallusinaatioita, ei käytön mukana kasvavia kustannuksia, välitöntä, suunniteltu toimimaan jokaisessa pull requestissa niin usein kuin tarvitaan.",
    point4: "Tarjoamme myös erillisiä tekoälytyökaluja — chatin, joka selittää tulokset, ja valinnaisen kerroksen, joka etsii hienovaraisempia logiikkavirheitä — mutta kumpikaan niistä ei koskaan päätä, onko jokin haavoittuvuus: se päätös pysyy aina 55 tarkistuksella, ja jokainen tekoälyn ehdotus on aina selvästi merkitty tarkistettavaksi, ei koskaan lisätä pisteisiin.",
